package com.example.petadoptioncommunity.media;
import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import com.example.petadoptioncommunity.identity.*;import com.example.petadoptioncommunity.web.Values;import java.util.*;import java.nio.file.*;import javax.imageio.ImageIO;
@Service public class MediaService {
 private final IdentityService identity;public MediaService(IdentityService i){identity=i;}
 public Object upload(IdentityPort.Actor a,MultipartFile file){return identity.withActiveActor(a,List.of(),()->{try{if(file.isEmpty()||file.getSize()>8*1024*1024)throw Values.bad("图片限8MB");try(var input=ImageIO.createImageInputStream(file.getInputStream())){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw Values.bad("请使用JPEG或PNG图片");var reader=readers.next();try{reader.setInput(input);String format=reader.getFormatName();if(!Set.of("JPEG","png","PNG","jpeg").contains(format)||((long)reader.getWidth(0)*reader.getHeight(0))>20000000)throw Values.bad("图片格式或像素尺寸不支持");var image=reader.read(0);Path directory=Path.of("../.local/uploads").toAbsolutePath().normalize();Files.createDirectories(directory);String name=UUID.randomUUID()+".png";ImageIO.write(image,"png",directory.resolve(name).toFile());return Map.of("url","/media/"+name);}finally{reader.dispose();}}}catch(java.io.IOException e){throw Values.bad("图片保存失败");}});}
}
